import{z as o,x as s,o as A,c as d,q as n,j as r,D as E,d as B,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"基准与数据集","description":"","frontmatter":{"title":"基准与数据集","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-benchmarks-datasets.md","filePath":"quant/dp-benchmarks-datasets.md","lastUpdated":1791063341000}'),p={name:"quant/dp-benchmarks-datasets.md"};function h(F,a,u,D,m,f){const t=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=n('<h1 id="基准与数据集" tabindex="-1">基准与数据集 <a class="header-anchor" href="#基准与数据集" aria-label="Permalink to &quot;基准与数据集&quot;">​</a></h1><div class="epigraph"><p>一个方向的成熟度，看它用什么防止自己骗自己：任务钉在预指定的基线上，数据钉在时点上，分数钉在多种子与显著性上——金融深度学习缺的从来不是架构，是这三枚钉子。</p><footer>—— 据 Diebold and Mariano, 1995；Bailey, Borwein, López de Prado and Zhu, 2014 整理</footer></div><p><a href="/quant/dp-model-risk">上一课</a>把深度管线的模型风险收进治理与台账；治理要有可比的底座，本课给底座：任务基线、数据集与评估协议。没有底座的领域会重复同一个故事：公共基准被反复调参，分数的抬升来自对切分的过拟合而不是方法——<a href="/quant/deep-lob-leakage">深度 LOB 泄漏</a>课把这条教训点过名，本课把它制度化：每个子领域配一张「任务 × 基线 × 指标」的配对表与一份时点清楚的数据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>漂移发生在三个层次。基线漂移：论文只与弱基线比，深度模型打赢随机初始化没有信息量——骨架课的要求是与 BS delta 比，波动率课的要求是与 HAR 比。数据漂移：供应商修订、公司行动与时点错误，让两篇论文用的「同名数据」不是同一分布；回测与实盘的差距常从数据层就拉开。协议漂移：切分方式、损失函数、种子与早停不报告，结果不可复现，跨论文比较退化为口口相传。金融的特殊困难在于：历史只有一条且不可重复，市场体制漂移让任何冻结协议都有保质期，数据昂贵且带许可约束——公开基准因此稀少而珍贵，也因此在被滥用后失真。</p><p><span class="marginnote">术语翻译：「基线」就是该任务上一个朴素但公认的方法——波动率预测的 HAR、微观信号的线性 OFI、执行里的 TWAP/VWAP。新模型先打赢它才有讨论价值；打赢「随机初始化的自己」不算赢。</span></p><h3 id="数据集的三层" tabindex="-1">数据集的三层 <a class="header-anchor" href="#数据集的三层" aria-label="Permalink to &quot;数据集的三层&quot;">​</a></h3><p>公开数据集按层次分：逐档簿数据（FI-2010、LOBSTER 类学术许可）、逐笔行情与报价（TAQ 类、交易所 ITCH 样例）、竞赛数据集（已实现波动预测、市场排序类竞赛赛题）。自建数据的关键不在规模而在时点纪律：<a href="/quant/point-in-time">时点数据</a>与<a href="/quant/no-future-function">无未来函数</a>的规则写进数据版本，清洗规则随数据发布——不然同名数据集在不同仓库里是不同动物。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配对表逐任务立：波动率预测配 HAR 基线与 QLIKE（<a href="/quant/qlike-vol-forecast-eval">评估协议</a>）；微观信号配 OFI 线性与经济价值指标；执行配 TWAP/VWAP/AC 与短缺分布；生成模型配签名距离加下游任务（<a href="/quant/generative-backtest-eval">生成式回测评估</a>）；定价校准配原模型价格差与无套利检查。协议件固定：按日或按期切分加禁运（<a href="/quant/purge-embargo">禁运与清洗</a>），多种子报分布而非单点，预测比较用 Diebold–Mariano 一类显著性检验，策略层结论加多重检验折价（<a href="/quant/deflated-sharpe">deflated Sharpe</a>、<a href="/quant/hansen-spa">SPA</a>）。报告规范：协议与方法一起发表——切分日历、预处理冻结点、随机种子属于方法，不是附录。</p><p><span class="marginnote">数字实例：多种子评估跑 10 个随机种子，报告均值加减标准差，而不是最好的那一个；若方法 A 的均值只比 B 高 0.1 个点、而种子间标准差有 0.5 个点，这个「提升」多半是抽签抽出来的。</span></p>',11)),(A(),r(i,null,{default:E(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%EF%BC%9A%E6%B3%A2%E5%8A%A8%2F%E4%BF%A1%E5%8F%B7%2F%E6%89%A7%E8%A1%8C%2F%E7%94%9F%E6%88%90%2F%E5%AE%9A%E4%BB%B7%22%5D%20--%3E%20PAIR%5B%22%E9%85%8D%E5%AF%B9%EF%BC%9A%E5%9F%BA%E7%BA%BF%20%2B%20%E6%8C%87%E6%A0%87%22%5D%0A%20%20DATA%5B%22%E6%95%B0%E6%8D%AE%E9%9B%86%EF%BC%9A%E6%97%B6%E7%82%B9%20%2B%20%E6%B8%85%E6%B4%97%E8%A7%84%E5%88%99%22%5D%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20PROTO%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E5%88%87%E5%88%86%20%2B%20%E7%A6%81%E8%BF%90%20%2B%20%E5%A4%9A%E7%A7%8D%E5%AD%90%22%5D%0A%20%20PROTO%20--%3E%20SIG%5B%22%E6%98%BE%E8%91%97%E6%80%A7%EF%BC%9ADM%20%E6%A3%80%E9%AA%8C%20%2B%20%E5%A4%9A%E9%87%8D%E6%8A%98%E4%BB%B7%22%5D%0A%20%20SIG%20--%3E%20REP%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%8D%8F%E8%AE%AE%E9%9A%8F%E6%96%B9%E6%B3%95%E5%8F%91%E8%A1%A8%22%5D%0A%20%20REP%20--%3E%20MON%5B%22%E5%9F%BA%E5%87%86%E5%A4%B1%E6%95%88%E7%9B%91%E6%8E%A7%EF%BC%9A%E4%BD%93%E5%88%B6%E4%B8%8E%E5%85%B1%E5%90%8C%E8%BF%87%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"基准失效的机制与模型过拟合同构：固定基准被社区反复优化，等于把验证集暴露给了整个领域的选择压力——FI-2010 的切分被调过太多次，其上的分数抬升已无法全部归因于方法。对策不是弃用基准而是轮换与分层：留出从未参与竞赛的时段与品种做最终确认，报告里区分「在共同基准上的相对位置」与「在新数据上的绝对表现」。公开数据集是双刃的机制也在此：它把社区的计算统一到一个点上，也把过拟合的能力统一到一个点上。",-1)),a[5]||(a[5]=e("p",null,"一张图看「共同过拟合」怎么发生、怎么挡：",-1)),(A(),r(i,null,{default:E(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20Bench%5B%22%E5%85%AC%E5%85%B1%E5%9F%BA%E5%87%86%3A%20%E5%88%87%E5%88%86%E5%9B%BA%E5%AE%9A%E5%85%AC%E5%BC%80%22%5D%20--%3E%20Many%5B%22%E5%85%A8%E7%A4%BE%E5%8C%BA%E5%8F%8D%E5%A4%8D%E8%B0%83%E5%8F%82%22%5D%0A%20%20Many%20--%3E%20Leak%5B%22%E9%80%89%E6%8B%A9%E5%8E%8B%E5%8A%9B%E6%B3%84%E6%BC%8F%E8%BF%9B%E5%88%87%E5%88%86%22%5D%0A%20%20Leak%20--%3E%20Infl%5B%22%E5%88%86%E6%95%B0%E6%8A%AC%E5%8D%87%2C%20%E4%B8%8D%E5%86%8D%E5%8F%AF%E5%BD%92%E5%9B%A0%E4%BA%8E%E6%96%B9%E6%B3%95%22%5D%0A%20%20Infl%20--%3E%20Fix%5B%22%E5%AF%B9%E7%AD%96%3A%20%E7%95%99%E5%87%BA%E4%BB%8E%E6%9C%AA%E5%8F%82%E8%B5%9B%E7%9A%84%E6%97%B6%E6%AE%B5%E4%B8%8E%E5%93%81%E7%A7%8D%22%5D%0A%20%20Fix%20--%3E%20Final%5B%22%E6%9C%80%E7%BB%88%E7%A1%AE%E8%AE%A4%3A%20%E7%9B%B8%E5%AF%B9%E4%BD%8D%E7%BD%AE%E4%B8%8E%E7%BB%9D%E5%AF%B9%E8%A1%A8%E7%8E%B0%E5%88%86%E5%BC%80%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：公共基准像一张用了多年的公开考卷——题库固定后，培训班专刷历年真题，高分不再等于能力强；对策是留几套从没公开的新卷，只在上考场那天拆封。</span></p><p><span class="marginnote">FI-2010 的教训在深度 LOB 课已点名：公共基准被反复调参后，分数抬升来自对切分的过拟合。任何基准的第一次使用就要预指定切分与基线，把协议与方法一起发表——迟到的纪律救不回已被污染的分数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准不覆盖容量与成本：基点级的改进在基准上显著、在实盘可能不覆盖冲击——经济价值指标必须与统计指标并列。数据集的代表性是硬边界：美股簿数据上的结论外推到其他市场结构要重新验证，机制可能普适、参数几乎必然不普适。评测结果的有效期与数据窗口绑定：跨期引用旧分数没有意义，体制变更后基线与挑战者要同台重跑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三个漂移层：基线、数据、协议；对策分别是配对表、时点纪律、协议随方法发表。</li><li>每个任务先立基线与指标，再谈架构：HAR、OFI、TWAP/AC、BS delta 各归各位。</li><li>公共基准会被共同过拟合：留出时段与品种做最终确认，区分相对位置与绝对表现。</li><li>统计显著与经济价值并列报告；基点级改进过不了成本折价就不算数。</li><li>出处：Diebold and Mariano, 1995；Bailey, Borwein, López de Prado and Zhu, 2014（deflated Sharpe）；Zhang, Zohren and Roberts, <em>IEEE TSP</em>, 2019（FI-2010）。</li></ul>',6))])}const P=o(p,[["render",h]]);export{C as __pageData,P as default};
